INSERT INTO `has_award` (`id`, `id_card`, `name`, `year`, `dateAdd`, `img`) VALUES
(1525, '3450900477521', 'ผลงานวิจัยระดับดีเพื่อการพัฒนาเชิงพื้นที่ การประชุมวิชาการระดับชาติ มหาวิทยาลัยราชภัฏ ครั้งที่ 2 การพัฒนาท้องถิ่นเพื่อแผ่นดินไทย : พัฒนาคุณภาพชีวิตของคนไทยในท้องถิ่น', '2554', '2024-03-01 13:09:59', NULL),
(1809, '3539900165241', 'โล่เกียรติคุณ \"รางวัลบุคลากรที่มีผลงานดีเด่น ด้านการส่งเสริมและการพัฒนานักศึกษา\" จากเครือข่ายความร่วมมือทางวิชาการ ระหว่างคณะวิทยาการจัดการ มหาวิทยาลัยราชภัฏกลุ่มภาคเหนือจำนวน 8 แห่ง ในการประชุมวิชาการระดับชาติครั้งที่ 11 และนานาชาติครั้งที่ 4 ณ มหาวิทยาลัยราชภัฏลำปาง', '2565', '2024-05-03 13:34:19', NULL),
(1808, '3539900165241', 'รางวัล \"นำเสนอบทความดีเด่น\" จากบทความเรื่อง \"การวิเคราะห์องค์ประกอบเชิงยืนยันเครื่องมือการสื่อสารการตลาดดิจิทัล\" ในการประชุมวิชาการระดับชาติครั้งที่ 11 และนานาชาติครั้งที่ 4 ณ มหาวิทยาลัยราชภัฏลำปาง (ผศ.ดร.กุลยา อุปพงษ์, ผศ.ดร.ศิริกาญจน์ ธรรมยัติวงศ์, อ.กมลวรรณ มั่งคั่ง, ดร.พลอยชมพู เชาวนปรีชา, ผศ.ธิดารัตน์ เหมือนเดชา และดร.ณัฐศิรี สมจิตรานุกิจ)', '2565', '2024-05-03 13:33:42', ''),
(1807, '3539900165241', 'โล่รางวัลและใบประกาศเชิดชูเกียรติ \"อาจารย์ที่ปรึกษาที่มีผลงานยอดเยี่ยมอันดับ 1\" ส่งนักศึกษาเข้าประกวดแข่งขัน 6 โครงการ เข้ารอบระดับมหาวิทยาลัย และเข้ารอบระดับประเทศ ทั้ง 6 โครงการ', '2565', '2024-05-03 13:32:56', NULL),
(1804, '3539900165241', 'โล่เชิดชูเกียรติ ทีมอาจารย์และนักศึกษาที่ผ่านเกณฑ์ระดับมหาวิทยาลัย และผ่านเกณฑ์ระดับประเทศ ในการประกวดแข่งขัน Startup Thailand League 2020', '2563', '2024-05-03 13:31:19', NULL),
(1805, '3539900165241', 'โล่เกียรติคุณ “นักบริการวิชาการดีเด่น” ภายใต้โครงการพัฒนาสมรรถนะอาจารย์และนักวิจัย การยกย่องนักวิจัยที่มีผลงานวิจัยและงานสร้างสรรค์ดีเด่น ประจำปี 2564', '2564', '2024-05-03 13:31:51', NULL),
(1806, '3539900165241', 'โล่รางวัลและใบประกาศเชิดชูเกียรติ “อาจารย์ที่ปรึกษา Startup ดีเด่น” จากการส่งผลงานเข้าร่วมประกวด Startup Thailand League 4 ปี เข้ารอบระดับมหาวิทยาลัยทั้ง 4 ปี (2560-2564) และเข้ารอบระดับประเทศ 2 ปีต่อเนื่อง (2563-2564)', '2564', '2024-05-03 13:32:26', NULL),
(1803, '3539900165241', 'รางวัล “นักบริหารจัดการงานวิจัยดี ระดับชุดโครงการ” ในการประชุมวิชาการระดับชาติมหาวิทยาลัยราชภัฏอุตรดิตถ์ : ราชภัฏวิชาการประจำปี 2560 “สืบสานศาสตร์พระราชาสู่พันธกิจสัมพันธ์ สร้างสรรค์การพัฒนาที่ยั่งยืน”', '2560', '2024-05-03 13:30:38', NULL),
(1801, '3539900165241', 'รางวัลเชิดชูเกียรติเพชรราชภัฏ “ดีเด่นด้านการสอน” ระดับหน่วยงาน มหาวิทยาลัยราชภัฎอุตรดิตถ์ (ปีพ.ศ. 2556)', '2556', '2024-05-03 13:29:40', NULL),
(1802, '3539900165241', 'โล่เกียรติคุณ “ศิษย์เก่าดีเด่น โรงเรียนอุตรดิตถ์ดรุณี”', '2557', '2024-05-03 13:30:08', NULL),
(1513, '3540600121151', 'รางวัลที่ปรึกษาสหกิจศึกษาและการศึกษาเชิงบูรณาการกับการทำงานดีเด่น', '2566', '2024-02-02 21:58:38', NULL),
(1512, '3540600121151', ' รางวัลเชิดชูเกียรตินักวิจัยต้นแบบที่ได้รับทุนวิจัยแหล่งทุนภายนอก เหรียญเงิน', '2566', '2024-02-02 21:58:17', NULL),
(1511, '3539800040251', 'นักวิจัยดีเด่นด้านการบูรณาการเรียนการสอนกับการวิจัย งานสัปดาห์วิทยาศาสตร์แห่งชาติ ส่วนภูมิภาค ปี 2562 คณะวิทยาศาสตร๋และเทคโนโลยี', '2562', '2024-01-31 11:29:16', ''),
(1800, '3539900165241', 'ใบประกาศเชิดชูเกียรติ “ผู้สอนดีเด่น” คณะวิทยาการจัดการ มหาวิทยาลัยราชภัฏอุตรดิตถ์ ประจำปี 2554', '2554', '2024-05-03 13:28:55', NULL),
(1515, '3570700358455', 'นักวิจัยดีเด่นด้านพันธกิจสัมพันธ์/ประกาศมหาวิทยาลัยราชภัฏอุตรดิตถ์ เรื่อง รางวัลเชิดชูเกียรตินักวิจัยต้นแบบ นักวิจัยดีเด่น ผลงานวิจัยดีเด่น มหาวิทยาลัยราชภัฏอุตรดิตถ์ เนื่องในวันราชภัฏ ประจำปี 2567', '2567', '2024-02-14 13:02:36', NULL),
(1514, '3540600121151', 'อาจารย์ผู้มีผลงานผ่านเกณฑ์ระดับมหาวิทยาลัยและเป็นผู้ร่วมสร้างโครงการStrat up Thailand League', '2564', '2024-02-02 21:59:09', NULL),
(1516, '3570700358455', 'นักวิจัยที่ได้รับทุนวิจัยจากแหล่งทุนภายนอก ระดับเหรีญทองแดง/พิธีมอบรางวัลเชิดชูเกียรติ นักวิจัยดีเด่น และผลงานวิจัยดีเด่น มหาวิทยาลัยราชภัฏอุตรดิตถ์ ปี 2566', '2566', '2024-02-14 13:16:21', ''),
